-- ************************************** retail_dw.core.fact_sales
CREATE TABLE retail_dw.core.fact_sales (
  sales_line_id bigint NOT NULL CONSTRAINT PK_5 PRIMARY KEY COMMENT 'Surrogate primary key for the sales line.',
  date_key int NOT NULL COMMENT 'FK to dim_date.',
  product_key bigint NOT NULL COMMENT 'FK to dim_product.',
  store_key int NOT NULL COMMENT 'FK to dim_store.',
  customer_key bigint COMMENT 'FK to dim_customer. Null for anonymous sales.',
  transaction_id string NOT NULL COMMENT 'Point-of-sale transaction identifier.',
  quantity int NOT NULL COMMENT 'Units sold.',
  gross_amount decimal(14,2) NOT NULL COMMENT 'Amount before discounts in USD.',
  discount_amount decimal(14,2) NOT NULL COMMENT 'Discount applied in USD.',
  net_amount decimal(14,2) NOT NULL COMMENT 'Amount after discounts in USD.',
  CONSTRAINT FK_1 FOREIGN KEY (date_key) REFERENCES retail_dw.core.dim_date (date_key),
  CONSTRAINT FK_2 FOREIGN KEY (product_key) REFERENCES retail_dw.core.dim_product (product_key),
  CONSTRAINT FK_3 FOREIGN KEY (store_key) REFERENCES retail_dw.core.dim_store (store_key),
  CONSTRAINT FK_4 FOREIGN KEY (customer_key) REFERENCES retail_dw.core.dim_customer (customer_key)
)
COMMENT 'Grain: one row per product per sale line item per transaction.'
TBLPROPERTIES (delta.columnMapping.mode = 'name');

SET TAG ON TABLE retail_dw.core.fact_sales DATA_DOMAIN;

-- ************************************** retail_dw.core.fact_inventory_snapshot
CREATE TABLE retail_dw.core.fact_inventory_snapshot (
  snapshot_id bigint NOT NULL CONSTRAINT PK_6 PRIMARY KEY COMMENT 'Surrogate primary key.',
  date_key int NOT NULL COMMENT 'FK to dim_date.',
  product_key bigint NOT NULL COMMENT 'FK to dim_product.',
  store_key int NOT NULL COMMENT 'FK to dim_store.',
  quantity_on_hand int NOT NULL COMMENT 'Units in stock at end of day.',
  reorder_point int COMMENT 'Stock level that triggers replenishment.',
  CONSTRAINT FK_5 FOREIGN KEY (date_key) REFERENCES retail_dw.core.dim_date (date_key),
  CONSTRAINT FK_6 FOREIGN KEY (product_key) REFERENCES retail_dw.core.dim_product (product_key),
  CONSTRAINT FK_7 FOREIGN KEY (store_key) REFERENCES retail_dw.core.dim_store (store_key)
)
COMMENT 'Grain: one row per product per store per day, periodic snapshot of stock on hand.'
TBLPROPERTIES (delta.columnMapping.mode = 'name');

SET TAG ON TABLE retail_dw.core.fact_inventory_snapshot DATA_DOMAIN;

CREATE OR REPLACE VIEW retail_dw.mart.vw_sales_summary (year_number int COMMENT 'Calendar year.', month_name string COMMENT 'Month name.', category_name string COMMENT 'Product category.', region_name string COMMENT 'Sales region.', units_sold bigint COMMENT 'Total units sold.', net_sales decimal(38,2) COMMENT 'Total net sales in USD.', transaction_count bigint COMMENT 'Distinct POS transactions.') AS
select d.year_number, d.month_name, p.category_name, s.region_name, sum(f.quantity) as units_sold, sum(f.net_amount) as net_sales, count(distinct f.transaction_id) as transaction_count from core.fact_sales f join core.dim_date d on f.date_key = d.date_key join core.dim_product p on f.product_key = p.product_key and p.is_current = true join core.dim_store s on f.store_key = s.store_key group by d.year_number, d.month_name, p.category_name, s.region_name;

CREATE OR REPLACE VIEW retail_dw.mart.vw_inventory_status (store_name string COMMENT 'Store name.', product_name string COMMENT 'Product name.', quantity_on_hand int COMMENT 'Units on hand.', reorder_point int COMMENT 'Replenishment trigger.', needs_reorder boolean COMMENT 'True when stock is at or below the reorder point.') AS
select s.store_name, p.product_name, f.quantity_on_hand, f.reorder_point, case when f.quantity_on_hand <= f.reorder_point then true else false end as needs_reorder from core.fact_inventory_snapshot f join core.dim_store s on f.store_key = s.store_key join core.dim_product p on f.product_key = p.product_key and p.is_current = true join core.dim_date d on f.date_key = d.date_key;

